def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, DAILY_SALARY * 0.35)

    cindy_bid = None
    highest_prev = 0.0
    urgent_opponents = 0
    weak_opponents = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if pbid is not None:
            pbid = float(pbid)
            if pbid > highest_prev:
                highest_prev = pbid
            if oid == 'Cindy':
                cindy_bid = pbid
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 3:
            urgent_opponents += 1
        if float(opp.get('budget', 0)) < DAILY_SALARY * 0.8 or float(opp.get('hp', 0)) <= 2:
            weak_opponents += 1

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    tightness = 1.0 - scarcity

    base = DAILY_SALARY * (0.34 + 0.18 * tightness)

    if cindy_bid is not None:
        if cindy_bid >= 120:
            base = max(base, 58.0 if hp > 3 and no_water_days == 0 else 82.0)
        elif cindy_bid >= 90:
            base = max(base, min(78.0, cindy_bid + 2.0))
        else:
            base = max(base, cindy_bid + 3.0)
    elif highest_prev > 0:
        base = max(base, min(75.0, highest_prev + 2.0))

    if no_water_days >= 2:
        base = max(base, 98.0)
    elif no_water_days == 1:
        base = max(base, 76.0 + 10.0 * tightness)

    if hp <= 2:
        base = max(base, 95.0)
    elif hp <= 4:
        base = max(base, 72.0 + 8.0 * tightness)

    if urgent_opponents >= 2 and hp > 4 and no_water_days == 0:
        base *= 0.9
    if weak_opponents >= 2 and hp > 3:
        base *= 0.94

    if day >= 8:
        base *= 1.08

    reserve_days = max(0, 10 - day)
    reserve = reserve_days * DAILY_SALARY * 0.28
    affordable = max(0.0, budget - reserve)
    if affordable <= 0:
        bid = min(budget, max(18.0, DAILY_SALARY * 0.22))
    else:
        bid = min(base, budget, max(affordable, 0.0))
        if no_water_days >= 1 or hp <= 3:
            bid = min(budget, max(bid, min(affordable + DAILY_SALARY * 0.2, 105.0)))

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    target_bid = DAILY_SALARY * 0.5 

    if yesterday_bids:
        highest_prev_opp_bid = max(yesterday_bids)
        lowest_prev_opp_bid = min(yesterday_bids)

        if highest_prev_opp_bid > DAILY_SALARY * 0.8 and my_hp > 3: 
            target_bid = DAILY_SALARY * 0.75 
        elif highest_prev_opp_bid > DAILY_SALARY * 0.4: 
            target_bid = highest_prev_opp_bid + 5 
        else: 
            target_bid = lowest_prev_opp_bid + 2 

    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 1.2) 

    if current_day == EPISODE_DAYS and my_hp > 0:
        return my_budget

    supply_ratio = (current_supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_bid_multiplier = 1.1 - (supply_ratio * 0.2)
    target_bid *= supply_bid_multiplier

    final_bid = min(my_budget, target_bid)
    final_bid = max(DAILY_SALARY * 0.2, final_bid) 

    return max(1.0, final_bid)
